if(!exists('override_monitoring',mode='function'))library(creditratingsystem)
target<-list(event='default',horizon=30,time_unit='days',probability_measure='PHYSICAL',conditioning='performing')
d<-list(model_id='reference',model_version='1',parameter_version='1',data_fingerprint='paired-cohorts',population_id='performing',split_id='holdout',prediction_origin='HOLDOUT',evaluation_cutoff='2020-03-01',target=target)
mt<-list(event='default',probability_measure='PHYSICAL',default_definition='contract-default-v1',unit='obligor',horizon_days=30,default_grade='D')
events<-lapply(c(1,3),function(i)list(event_id=paste0('d',i),entity_id=paste0('e',i),event='default',event_at='2020-01-15',known_at='2020-01-16',default_definition=mt$default_definition))
coverage<-lapply(0:3,function(i)list(entity_id=paste0('e',i),complete_through='2020-01-31',known_at='2020-02-01'))
entries<-list()
for(model in c('reference','candidate')){pd<-if(model=='reference')c(.1,.8,.3,.6)else c(.2,.7,.4,.5);predictions<-lapply(0:3,function(i)list(forecast_id=paste0(model,i),case_id=paste0('c',i),entity_id=paste0('e',i),cluster_id=paste0('g',i),cohort='2020-01',segment='all',model_id=model,model_version='1',forecast_at='2020-01-01',known_at='2020-01-01',pd=pd[i+1],weight=1,target=mt,prediction_origin='HOLDOUT'));entries[[model]]<-list(cohort=build_monitoring_cohorts(predictions,events,coverage,target_contract=mt,evaluation_cutoff='2020-03-01')$value,model_version='1',parameter_version='1',model_fingerprint=paste0('frozen-',model),training_known_at='2019-01-01')}
policy<-list(approved_authorities='committee',reference='approved-policy',concentration_threshold=.6)
ledger<-lapply(0:3,function(i)list(override_id=paste0('o',i),case_id=paste0('c',i),reason='evidence',authority='committee',applied_at='2019-12-30',known_at='2019-12-30',expires_at='2020-02-01',from_pd=c(.1,.8,.3,.6)[i+1],to_pd=c(.2,.7,.4,.5)[i+1]))
ledger[[1]]$to_pd<-.15;extra<-ledger[[1]];extra$override_id<-'o4';extra$applied_at<-extra$known_at<-'2019-12-31';extra$from_pd<-.15;extra$to_pd<-.2;ledger[[5]]<-extra;expired<-ledger[[2]];expired$override_id<-'expired';expired$applied_at<-expired$known_at<-'2019-01-01';expired$expires_at<-'2019-12-01';ledger[[6]]<-expired
run<-function()override_monitoring(entries$reference,entries$candidate,ledger,policy=policy,design=d,metrics='brier',uncertainty='none')$value
r<-run();stopifnot(r$metrics$override_rate==1,r$metrics$pd_increase_cases==2,r$metrics$pd_decrease_cases==2,identical(r$diagnostics$multiple_active_case_ids,list('c0')),identical(r$diagnostics$expired_override_ids,list('expired')),r$metrics$concentration$authority$flag,abs(r$metrics$paired_performance$paired_differences$candidate$brier$difference-.06)<1e-14,!r$diagnostics$causal_effect_identified)
ledger[[1]]$from_pd<-.7;stopifnot(inherits(try(run(),silent=TRUE),'try-error'))
# Separately observed event stages: one shared event counts once in the union.
d$currency<-'EUR';stagenames<-c('entity','transfer','joint','final','counterfactual','guarantee');contract<-setNames(lapply(stagenames,function(s)list(kind=if(s=='guarantee')'amount'else'binary',observable=s!='counterfactual',event_definition=paste0(s,'-definition'),reference='staged-events')),stagenames);contract$guarantee$currency<-'EUR';union<-list(component_a='entity',component_b='transfer',joint='joint',union='final');rows<-lapply(0:1,function(i){outcomes<-setNames(lapply(setdiff(stagenames,'counterfactual'),function(s)list(value=if(s=='guarantee')if(i==0)20 else 0 else 1-i,known_at='2020-02-01',complete_through='2020-01-31',event_ids=if(i==0)list(paste0('shared',i))else list(),event_times=if(i==0)list('2020-01-15')else list())),setdiff(stagenames,'counterfactual'));list(prediction_id=paste0('p',i),entity_id=paste0('e',i),cluster_id=paste0('g',i),segment='all',as_of='2020-01-01',forecast_known_at='2020-01-01',horizon_end='2020-01-31',model_id='reference',model_version='1',parameter_version='1',stage_predictions=list(entity=.2,transfer=.1,joint=.05,final=.25,counterfactual=.3,guarantee=30),stage_outcomes=outcomes)})
srun<-function()support_transfer_backtest(rows,stage_contract=contract,union_contract=union,design=d,uncertainty='cluster_bootstrap',cluster_resamples=list(c('g0','g0'),c('g1','g1')))$value
r<-srun();stopifnot(r$metrics$by_stage$final$brier==.3125,r$metrics$by_stage$guarantee$bias==20,r$metrics$by_stage$counterfactual$applicability=='NOT_APPLICABLE',r$diagnostics$event_reconciliation[[1]]$distinct_component_event_count==1,r$diagnostics$event_reconciliation[[2]]$distinct_component_event_count==0,abs(r$uncertainty$intervals[['guarantee/bias']]$lower-10.5)<1e-14)
rows[[1]]$stage_predictions$final<-.3;stopifnot(inherits(try(srun(),silent=TRUE),'try-error'))
